import httpx, json, sys

HERMES_API = "http://localhost:8100"

system = "Kamu Senator Akademisi Upshalter. Analisa riset AI, teknologi, pendidikan Indonesia. JSON output."
prompt = "Riset perkembangan AI di Indonesia hari ini. Temukan 3 hal paling signifikan. Format: {temuan:[...], sumber:[...]}"

try:
    for endpoint in ["/v1/chat/completions", "/v1/portsocket", "/chat"]:
        try:
            print(f"Trying {endpoint}...", file=sys.stderr)
            r = httpx.post(HERMES_API + endpoint, json={
                "messages": [
                    {"role":"system","content":system},
                    {"role":"user","content":prompt}
                ],
                "stream": False
            }, timeout=90)
            print(f"  Status: {r.status_code}", file=sys.stderr)
            if r.status_code == 200:
                d = r.json()
                content = (d.get("choices",[{}])[0].get("message",{}).get("content") or
                          d.get("response") or d.get("content",""))
                if content:
                    print(f"SUCCESS via {endpoint}", file=sys.stderr)
                    print(content[:500])
                    exit(0)
                else:
                    print(f"  Empty response, keys: {list(d.keys())}", file=sys.stderr)
            else:
                print(f"  Body: {r.text[:200]}", file=sys.stderr)
        except Exception as e:
            print(f"  Error: {e}", file=sys.stderr)
            continue
    print("ALL_ENDPOINTS_FAILED")
except Exception as e:
    print(f"FATAL: {e}")
PYEOF
' 2>&1", "timeout": 130}

